From dd0d10b09b94a09ad3d20401c4fca267a022cb5f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:23:17 +0100
Subject: [PATCH] containments/desktop: show app names for launchers in custom
 folders

Launchers were only labelled with their Name when the desktop showed the
Desktop folder through desktop:/, so any other location showed the file
name. Now the desktop parses them in every location, like on desktop:/.

BUG: 511746
---
 .../package/contents/ui/FolderView.qml        |  2 +-
 .../desktop/plugins/folder/foldermodel.cpp    | 20 ++++++++++++++++++-
 2 files changed, 20 insertions(+), 2 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..656cfec133 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1228,7 +1228,7 @@ FocusScope {
             usedByContainment: root.isContainment && main.isRootView
             sortDesc: Plasmoid.configuration.sortDesc
             sortDirsFirst: Plasmoid.configuration.sortDirsFirst
-            parseDesktopFiles: (Plasmoid.configuration.url === "desktop:/")
+            parseDesktopFiles: root.isContainment || Plasmoid.configuration.url === "desktop:/"
             previews: Plasmoid.configuration.previews
             previewPlugins: Plasmoid.configuration.previewPlugins
             applet: Plasmoid
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..f083ca3479 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -933,6 +933,16 @@ void FolderModel::rename(int row, const QString &name)
     }

     const KFileItem oldItem = itemForIndex(idx);
+    if (m_parseDesktopFiles && oldItem.isDesktopFile() && oldItem.url().isLocalFile()) {
+        if (!name.isEmpty() && name != data(idx, Qt::DisplayRole).toString()) {
+            KDesktopFile file(oldItem.localPath());
+            KConfigGroup group = file.desktopGroup();
+            group.writeEntry("Name", name);
+            group.writeEntry("Name", name, KConfigGroup::Persistent | KConfigGroup::Localized);
+            group.sync();
+        }
+        return;
+    }
     if (name.isEmpty() || name == oldItem.text() || name == QLatin1Char('.') || name == QLatin1String("..")) {
         return;
     }
@@ -1540,6 +1550,14 @@ QVariant FolderModel::data(const QModelIndex &index, int role) const

     if (role == BlankRole) {
         return m_dragIndexes.contains(index);
+    } else if (role == Qt::DisplayRole) {
+        const KFileItem item = itemForIndex(index);
+        if (m_parseDesktopFiles && item.isDesktopFile() && item.url().isLocalFile()) {
+            const QString name = KDesktopFile(item.localPath()).readName();
+            if (!name.isEmpty()) {
+                return name;
+            }
+        }
     } else if (role == SelectedRole) {
         return m_selectionModel->isSelected(index);
     } else if (role == IsDirRole) {
@@ -1575,7 +1593,7 @@ QVariant FolderModel::data(const QModelIndex &index, int role) const
     } else if (role == FileNameRole) {
         return itemForIndex(index).url().fileName();
     } else if (role == FileNameWrappedRole) {
-        return KStringHandler::preProcessWrap(itemForIndex(index).text());
+        return KStringHandler::preProcessWrap(data(index, Qt::DisplayRole).toString());
     }

     return QSortFilterProxyModel::data(index, role);
-- 
